{"description":"Fetch yesterday's Bitcoin price from CoinGecko and store in btc_prices","id":"daily_btc","schedule":"0 8 * * *","steps":"[
  {"type":"fetch","url":"https://api.coingecko.com/api/v3/coins/bitcoin/history?date={{yesterday}}"},
  {"type":"transform","script":"let data = JSON.parse(input);
let date = new Date(); date.setDate(date.getDate()-1);
let formatted = date.toISOString().split('T')[0];
return {date: formatted, open: data.market_data.current_price.usd, close: data.market_data.current_price.usd, volume: data.market_data.total_volume.usd};"},
  {"type":"write","table":"btc_prices","mode":"insert"}
]"}

