{"description":"Check BTC price drop >5% and send Telegram alert","id":"btc_drop_alert","schedule":"30 7 * * 1-5","steps":"[
  {"type":"query","sql":"SELECT date, close FROM btc_prices ORDER BY date DESC LIMIT 2"},
  {"type":"transform","script":"let rows = JSON.parse(input);
if (rows.length < 2) return null;
let latest = rows[0];
let prev = rows[1];
let drop = (prev.close - latest.close) / prev.close * 100;
if (drop >= 5) {
  return {message: `⚠️ Bitcoin price dropped ${drop.toFixed(2)}% since ${prev.date}. Current: ${latest.close} EUR.`};
}
return null;"},
  {"type":"notify","channel":"telegram","payload":"{{input}}"}
]"}

